#include <stdio.h>
#include <string.h>
#include <stdlib.h>
int is_prime(long long n) {
    if (n < 2) return 0;
    if (n == 2 || n == 3) return 1;
    if (n % 2 == 0 || n % 3 == 0) return 0;
    for (long long i = 5; i * i <= n; i += 6)
        if (n % i == 0 || n % (i + 2) == 0) return 0;
    return 1;
}
int main() {
    char s[50]; if (scanf("%s", s) != 1) return 0;
    int len = strlen(s), circ = 1;
    char rot[50];
    for (int i = 0; i < len; i++) {
        int idx = 0;
        for (int j = i; j < len; j++) rot[idx++] = s[j];
        for (int j = 0; j < i; j++) rot[idx++] = s[j];
        rot[idx] = '\0';
        if (!is_prime(atoll(rot))) { circ = 0; break; }
    }
    printf("%s\n", circ ? "CIRCULAR PRIME" : "NOT CIRCULAR PRIME");
    return 0;
}

